D6=$(date -v+6d +%Y-%m-%d)
C='[data-slot=date-picker-content]'
echo "[{\"click\":\"[data-slot=date-picker-trigger]\",\"wait\":90,\"snap\":\"mid-open\"},{\"wait\":1200,\"snap\":\"open\"},{\"click\":\"$C [data-slot=calendar-next]\",\"wait\":1200,\"snap\":\"next\"},{\"click\":\"$C [data-slot=calendar-previous]\",\"wait\":1200},{\"click\":\"$C [data-slot=calendar-day][data-value='$D6']\",\"wait\":60,\"snap\":\"mid-close\"},{\"wait\":1200,\"snap\":\"picked\"},{\"click\":\"[data-slot=date-picker-trigger]\",\"wait\":1000},{\"press\":\"ArrowRight\",\"wait\":200},{\"press\":\"ArrowDown\",\"wait\":600,\"snap\":\"keys\"},{\"press\":\"Escape\",\"wait\":900,\"snap\":\"escaped\"},{\"click\":\"[data-slot=date-picker-trigger]\",\"wait\":1000},{\"click\":\"[data-slot=date-picker-preset]:nth-child(2)\",\"wait\":1200,\"snap\":\"preset\"}]"
